from pathlib import Path
import json,csv
import mpmath as mp
ROOT=Path(__file__).resolve().parents[1]; RES=ROOT/'results';mp.mp.dps=80
tau=mp.mpf(1)/72;kappa=mp.mpf(81)/3689;c=mp.mpf('299792458');hbar=mp.mpf('1.054571817e-34');G=mp.mpf('6.67430e-11');E=mp.sqrt(hbar*c**5/(8*mp.pi*kappa*G));L=hbar*c/E;T=hbar/E;lp=mp.sqrt(hbar*G/c**3);S0=mp.mpf(4)/tau;g=mp.mpf(42);z=g*mp.e**(-S0);lambda_suppress=z;lambda_add=-mp.log(1+z);lam_req=mp.mpf('3.499535415592278e-124')
rows=[('tau',mp.nstr(tau,50)),('kappa_R',mp.nstr(kappa,50)),('E_star_J_from_G_anchor',mp.nstr(E,50)),('L_star_m_from_G_anchor',mp.nstr(L,50)),('T_star_s_from_G_anchor',mp.nstr(T,50)),('L_star_over_lPlanck',mp.nstr(L/lp,50)),('S0_4_over_tau',mp.nstr(S0,50)),('42_exp_minus_288',mp.nstr(z,60)),('candidate_over_prior_required',mp.nstr(z/lam_req,50)),('relative_difference_to_prior_required',mp.nstr((z-lam_req)/lam_req,50)),('lambda_if_additive_extra_states',mp.nstr(lambda_add,60)),('lambda_if_suppressive_free_energy_density',mp.nstr(lambda_suppress,60))]
with (RES/'27_regge_volume_coefficients.csv').open('w',newline='') as f:w=csv.writer(f);w.writerow(['quantity','value']);w.writerows(rows)
summary={'regge_action':'S_R/hbar = kappa_R sum_h Ahat_h delta_h - lambda_R sum_sigma Vhat_sigma + ...','curvature_matching':'G = hbar c^5/(8 pi kappa_R E_*^2)','volume_matching':'Lambda L_*^2 = lambda_R/kappa_R','induced_volume_exact_identity':'lambda_R^ind=-(1/N4) log(Z_Omega/Z_flat)','cumulant_identity':'lambda_R^ind=(1/N4) sum_{n>=1} (-1)^(n+1) kappa_n(Delta S)/n!, for Z/Z0=<exp(-Delta S)>_0','kappa_R_exact':'81/3689','tau_exact':'1/72','dilute_saddle_hypothesis':{'degeneracy_g':42,'action_S0':'4/tau=288','fugacity':mp.nstr(z,60),'theorem':'If the connected free-energy density generated by a 42-fold saddle family of action 288 is z+O(z^2), i.e. log(Z/Z_flat)=-N4 z+O(N4 z^2), then lambda_R^ind=42 exp(-288)+O(exp(-576)).','sign_note':'A naive additional-state factor (1+z)^N gives the opposite sign; positive lambda requires a suppressive/free-energy contribution, which is part of the microscopic saddle calculation.'},'G_anchor_scale':{'E_star_J':mp.nstr(E,40),'L_star_m':mp.nstr(L,40),'T_star_s':mp.nstr(T,40),'L_over_lPlanck':mp.nstr(L/lp,40)},'prior_required_comparison_only':{'lambda_required':mp.nstr(lam_req,40),'ratio_candidate_required':mp.nstr(z/lam_req,40)}}
(RES/'28_regge_volume_functional_theorem.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
